alter table public.assistant_knowledge
  drop constraint if exists assistant_knowledge_status_check;

alter table public.assistant_knowledge
  add constraint assistant_knowledge_status_check
  check (status = any (array['pending'::text, 'approved'::text, 'disabled'::text]));

alter table public.assistant_knowledge
  alter column status set default 'pending';

-- Previously auto-approved answers were generated by the model without human review.
-- Keep them out of shared-answer retrieval until they are reviewed.
update public.assistant_knowledge
set status = 'pending'
where status = 'approved';
